bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || exit 61
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';import{readFileSync}from'node:fs';
const e=process.env,db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,
 user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,
 password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),
 max:1,connectionTimeoutMillis:5000});
try{
 const q=await db.query(
 "SELECT p.title,p.price_stars,p.status AS product_status,t.status AS post_status,t.chat_id,t.message_thread_id,t.telegram_message_id,t.display_text FROM videobot_sticker_products p LEFT JOIN videobot_sticker_topic_posts t ON t.product_id=p.product_id WHERE p.product_id=$1",
 ['sp_76f23430d1c29ca355960a95']);
 if(q.rowCount!==1)throw Error('STK_NATIVE_PRODUCT_MISSING');
 const x=q.rows[0];process.stdout.write('STK_NATIVE_PRODUCT_PRICE='+x.price_stars+'\n');
 process.stdout.write('STK_NATIVE_PRODUCT_STATUS='+x.product_status+'\n');
 process.stdout.write('STK_NATIVE_POST_STATUS='+x.post_status+'\n');
 process.stdout.write('STK_NATIVE_POST_CHAT='+x.chat_id+'\n');
 process.stdout.write('STK_NATIVE_POST_THREAD='+x.message_thread_id+'\n');
 process.stdout.write('STK_NATIVE_POST_MESSAGE='+x.telegram_message_id+'\n');
 process.stdout.write('STK_NATIVE_STORED_CAPTION_KIND='+
 (String(x.display_text||'').includes('ステッカー・絵文字パックの固定版素材')?'VERBOSE':
  String(x.display_text||'')==='🎨 '+x.title?'MINIMAL':'OTHER')+'\n');
}finally{await db.end();}
NODE
test "$(systemctl --user is-active gace-userbot-verify.service)" = active || { echo STK_USERBOT_RESIDENT_INACTIVE; exit 62; }
echo STK_USERBOT_RESIDENT_ACTIVE=PASS
for root in "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot" "$HOME/Project/Gserver/projects";do
 if test -d "$root";then
  grep -RFl --include='*.py' 'room_public_readback' "$root/scripts" "$root/artifacts" 2>/dev/null | head -n 4 || true
 fi
done
echo STK_IMAGE_PAYWALL_INSPECT_NO_MUTATION=PASS
